  ('3cec608d-b0b1-45c3-8b16-04113cadced7', 'cc17613d-6730-4d76-af05-323bc6b3f174', 'CO2035', 'Xử lý Tín hiệu số', NULL, '31d4086f-5184-483e-b1cb-d86c23f0cfca', 'L1.2', 'Xác định các đặc tính của hệ thống tuyến tính bất biến (LTI) như tính nhân quả và tính ổn định.', 'Determine characteristics of linear time-invariant (LTI) systems such as causality and stability.', 2, now(), now());
INSERT INTO course_management.subject_learning_outcomes
